<template><section v-if="value" class="learning-summary"><h3>Learning enrollment · {{value.program}}</h3><p>Grade {{value.grade||'not specified'}} · {{value.subject||'Subject to discuss'}} · {{value.format||'Format to discuss'}}</p><p v-for="[key,label] in fields" :key="key"><template v-if="value[key]"><strong>{{label}}:</strong> {{value[key]}}</template></p><template v-if="value.packageSnapshot"><h4>Requested package: {{value.packageSnapshot.name}}</h4><p>Quoted at inquiry: {{money(value.packageSnapshot.totalCents)}}. Confirm the plan and payment arrangements before enrollment.</p><ul><li v-for="(c,i) in value.packageSnapshot.components" :key="i">{{c.sessions}} × {{c.minutes}} minutes · {{c.service}} · {{c.format}} · {{c.educationLevel}} · {{money(c.totalCents)}}</li></ul></template><details v-if="Object.keys(value.reflectionAnswers||{}).length"><summary>Academic & emotional reflection · {{value.reflectionVersion||'parent'}}</summary><p>Observations for planning; no diagnostic score or eligibility threshold.</p><div v-for="group in reflections[value.reflectionVersion||'parent']||[]" :key="group.category"><h4>{{group.category}}</h4><p v-for="item in group.items.filter(i=>value.reflectionAnswers?.[i.id])" :key="item.id">{{item.text}} — {{value.reflectionAnswers[item.id]}} / 4</p></div></details></section></template>
<script setup>
import reflections from '../../navigation/learningReflection.js';defineProps({value:Object});const fields=[['strengths','Strengths'],['goals','Goals'],['schoolSupports','School supports'],['emotionalNeeds','Emotional and learning needs'],['funding','Funding to discuss']];const money=c=>c==null?'Contact us for pricing':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
</script>
<style scoped>.learning-summary{padding:20px;background:#f0f8f9;border:1px solid #ccdfe3;border-radius:10px;margin:20px 0}.learning-summary p{white-space:pre-wrap;overflow-wrap:anywhere}</style>
